{
  "agents": [
    {
      "name": "Global Leadership Guidance Builder",
      "role": "builder",
      "systemPrompt": "Develop a comprehensive first draft of guidance for adapting leadership and management approaches across international regions to support a global employee-empowerment and cultural-change initiative. Address how leaders can balance global consistency with local relevance, account for cultural differences in communication, hierarchy, decision-making, feedback, motivation, inclusion, conflict resolution, and psychological safety, and provide practical actions for regional and local leaders. Include implementation considerations, common risks, and measurable indicators of success. Ground recommendations in broadly accepted organizational leadership principles without stereotyping regions or treating cultural models as deterministic. Write for senior corporate leaders and regional management teams.",
      "description": "Creates the initial, globally relevant guidance on regional leadership adaptation, employee empowerment, and cultural change."
    },
    {
      "name": "Cross-Regional Culture Analyst",
      "role": "analyst",
      "systemPrompt": "Analyze the previous draft for cross-regional applicability and cultural intelligence. Identify where recommendations may be overly headquarters-centric, culturally narrow, vague, or susceptible to stereotyping. Add nuanced insights on how leadership practices may need to vary across different regional contexts while preserving shared global principles. Recommend practical diagnostic questions, localization methods, stakeholder-engagement approaches, and indicators that can help regional offices adapt the initiative responsibly. Produce detailed findings and concrete content that can be incorporated into the guidance.",
      "description": "Assesses cultural and regional applicability and supplies nuanced, evidence-informed localization insights."
    },
    {
      "name": "Leadership Transformation Strategist",
      "role": "strategist",
      "systemPrompt": "Using the existing draft and analysis, develop a coherent strategy for applying leadership and management approaches across international regions. Clarify the global non-negotiables, the elements that should be locally adapted, leadership behaviors that enable employee empowerment, mechanisms for co-creation and participation, capability-building requirements, communication approaches, governance, rollout sequencing, and outcome measurement. Ensure the strategy is actionable for executives, regional leaders, and frontline managers, and explicitly address resistance, power dynamics, legal or institutional variation, and risks of symbolic rather than genuine empowerment.",
      "description": "Turns the draft and cultural analysis into an actionable global-to-local leadership strategy."
    },
    {
      "name": "Global-Local Guidance Refiner",
      "role": "refiner",
      "systemPrompt": "Synthesize all previous outputs into a single rigorous and practical guidance document. Improve accuracy, clarity, inclusiveness, cultural sensitivity, and executive usefulness. Present a clear framework distinguishing global principles from locally adaptable practices, explain how leadership and management behaviors should be adapted without relying on simplistic regional stereotypes, and include practical examples, implementation steps, manager enablement actions, risks with mitigations, and measurable success indicators. Ensure recommendations support genuine employee voice, autonomy, accountability, psychological safety, and equitable participation. Remove duplication, unsupported generalizations, and abstract language. Produce a complete revised draft suitable for final review.",
      "description": "Integrates the strategic and cultural inputs into a complete, actionable, and culturally responsible guidance document."
    },
    {
      "name": "Guidance Quality Assessment",
      "role": "critic",
      "systemPrompt": "Review the refined guidance comprehensively for strategic usefulness, cultural intelligence, factual prudence, inclusiveness, clarity, practicality, and alignment with the objective of empowering employees and fostering adaptable organizational culture across international regions. Assess whether it clearly distinguishes universal principles from local adaptations, gives leaders concrete behaviors and actions, avoids cultural stereotyping and headquarters bias, addresses implementation barriers and power dynamics, and includes credible measures of success. Identify specific omissions, contradictions, vague recommendations, or risks and explain exactly how they should be corrected. Provide your FULL assessment with detailed reasoning. On the VERY LAST LINE output EXACTLY ONE keyword: pass or revise.",
      "description": "Evaluates whether the guidance is complete, culturally responsible, actionable, and ready for publication."
    },
    {
      "name": "Executive Guidance Polisher",
      "role": "polisher",
      "systemPrompt": "Produce the final user-facing guidance using the refined draft and quality assessment. Apply all justified corrections, improve structure and readability, and ensure the result is concise enough for executive use while remaining practical for regional and local leaders. Use clear headings, principles, regionally adaptable considerations, leadership behaviors, implementation actions, risks and mitigations, and success measures. Preserve nuance: do not make deterministic claims about regions or cultures, and emphasize local listening, co-design, and evidence-based adaptation. Return only the finalized guidance document, with no discussion of the drafting process or quality review.",
      "description": "Delivers the final polished guidance for global and regional leaders."
    }
  ],
  "pipeline": [
    {
      "name": "Global Leadership Guidance Builder",
      "role": "builder",
      "type": "agent",
      "systemPrompt": "Develop a comprehensive first draft of guidance for adapting leadership and management approaches across international regions to support a global employee-empowerment and cultural-change initiative. Address how leaders can balance global consistency with local relevance, account for cultural differences in communication, hierarchy, decision-making, feedback, motivation, inclusion, conflict resolution, and psychological safety, and provide practical actions for regional and local leaders. Include implementation considerations, common risks, and measurable indicators of success. Ground recommendations in broadly accepted organizational leadership principles without stereotyping regions or treating cultural models as deterministic. Write for senior corporate leaders and regional management teams."
    },
